/* Prix–taux : duration (tangente) vs duration + convexité */
(function () {
  var svg = document.getElementById("dur-chart");
  if (!svg) return;
  function v(id){ return parseFloat(document.getElementById(id).value); }
  function setT(id,t){ var e=document.getElementById(id); if(e) e.textContent=t; }
  function al(){ return document.body.getAttribute("data-active-lang")||"fr"; }

  function price(c,T,y){ var P=0; for(var t=1;t<=T;t++){ var cf=(t<T)?c:(c+100); P+=cf/Math.pow(1+y,t); } return P; }
  function metrics(c,T,y){
    var P=price(c,T,y), D=0, Cx=0;
    for(var t=1;t<=T;t++){ var cf=(t<T)?c:(c+100); var pv=cf/Math.pow(1+y,t); D+=t*pv; Cx+=t*(t+1)*cf/Math.pow(1+y,t+2); }
    D=D/P; return { P:P, Dmac:D, Dmod:D/(1+y), Cx:Cx/P, dv01:(D/(1+y))*P*0.0001 };
  }

  function draw(){
    var cpct=v("dur-c"), T=Math.round(v("dur-T")), ypct=v("dur-y");
    var yunit = al()==="fr" ? " ans" : (al()==="nl" ? " jaar" : " yr");
    setT("dur-c-o", cpct.toFixed(1)+"%"); setT("dur-T-o", T+yunit); setT("dur-y-o", ypct.toFixed(2)+"%");
    var c=cpct, y0=ypct/100;
    var m=metrics(c,T,y0);
    setT("dur-price", m.P.toFixed(2));
    setT("dur-dmac", m.Dmac.toFixed(2));
    setT("dur-dmod", m.Dmod.toFixed(2));
    setT("dur-dv01", m.dv01.toFixed(4));
    setT("dur-cx", m.Cx.toFixed(1));

    var W=520,H=260,L=46,R=14,T2=16,B=32, pw=W-L-R, ph=H-T2-B;
    var xmin=Math.max(0.0005, y0-0.03), xmax=y0+0.03;
    var N=90, xs=[], pt=[];
    for (var i=0;i<=N;i++){ var yy=xmin+(xmax-xmin)*i/N; xs.push(yy); pt.push(price(c,T,yy)); }
    // duration & convexity estimates across range
    function pDur(yy){ return m.P*(1 - m.Dmod*(yy-y0)); }
    function pDC(yy){ var d=yy-y0; return m.P*(1 - m.Dmod*d + 0.5*m.Cx*d*d); }
    var pmin=Infinity,pmax=-Infinity;
    for (var j=0;j<=N;j++){ pmin=Math.min(pmin,pt[j],pDur(xs[j])); pmax=Math.max(pmax,pt[j],pDur(xs[j])); }
    var pad=(pmax-pmin)*0.06; pmin-=pad; pmax+=pad;
    function px(yy){ return L + (yy-xmin)/(xmax-xmin)*pw; }
    function py(pp){ return T2 + (1-(pp-pmin)/(pmax-pmin))*ph; }

    var g="";
    // axes
    g+='<line class="axis" x1="'+L+'" y1="'+T2+'" x2="'+L+'" y2="'+(T2+ph)+'"/>';
    g+='<line class="axis" x1="'+L+'" y1="'+(T2+ph)+'" x2="'+(L+pw)+'" y2="'+(T2+ph)+'"/>';
    // duration line (gold, straight)
    g+='<line x1="'+px(xmin).toFixed(1)+'" y1="'+py(pDur(xmin)).toFixed(1)+'" x2="'+px(xmax).toFixed(1)+'" y2="'+py(pDur(xmax)).toFixed(1)+'" stroke="var(--gold)" stroke-width="2" stroke-dasharray="1 0"/>';
    // duration + convexity (crimson dashed)
    var dc="M "+px(xs[0]).toFixed(1)+","+py(pDC(xs[0])).toFixed(1);
    for (var k=1;k<=N;k++) dc+=" L "+px(xs[k]).toFixed(1)+","+py(pDC(xs[k])).toFixed(1);
    g+='<path d="'+dc+'" fill="none" stroke="var(--crimson)" stroke-width="1.8" stroke-dasharray="5 3"/>';
    // true price curve (teal, thick)
    var tp="M "+px(xs[0]).toFixed(1)+","+py(pt[0]).toFixed(1);
    for (var k2=1;k2<=N;k2++) tp+=" L "+px(xs[k2]).toFixed(1)+","+py(pt[k2]).toFixed(1);
    g+='<path d="'+tp+'" fill="none" stroke="var(--teal)" stroke-width="2.6"/>';
    // anchor point
    g+='<circle cx="'+px(y0).toFixed(1)+'" cy="'+py(m.P).toFixed(1)+'" r="4" fill="var(--ink)"/>';
    g+='<line class="axis" x1="'+px(y0).toFixed(1)+'" y1="'+py(m.P).toFixed(1)+'" x2="'+px(y0).toFixed(1)+'" y2="'+(T2+ph)+'" stroke-dasharray="3 3" stroke-width="1"/>';
    // ticks x
    g+='<text class="tick" x="'+L+'" y="'+(H-16)+'" text-anchor="start">'+(xmin*100).toFixed(1)+'%</text>';
    g+='<text class="tick" x="'+px(y0).toFixed(1)+'" y="'+(H-16)+'" text-anchor="middle">'+(y0*100).toFixed(1)+'%</text>';
    g+='<text class="tick" x="'+(L+pw)+'" y="'+(H-16)+'" text-anchor="end">'+(xmax*100).toFixed(1)+'%</text>';
    // ticks y
    g+='<text class="tick" x="'+(L-6)+'" y="'+(py(pmax)+4).toFixed(1)+'" text-anchor="end">'+pmax.toFixed(0)+'</text>';
    g+='<text class="tick" x="'+(L-6)+'" y="'+(py(pmin)+4).toFixed(1)+'" text-anchor="end">'+pmin.toFixed(0)+'</text>';
    // axis labels
    var xlab = al()==="en"?"yield":(al()==="nl"?"rendement":"taux (y)");
    var ylab = al()==="en"?"price":(al()==="nl"?"prijs":"prix");
    g+='<text class="lab" x="'+(L+pw/2)+'" y="'+(H-3)+'" text-anchor="middle">'+xlab+'</text>';
    g+='<text class="lab" x="'+(L-34)+'" y="'+(T2+ph/2)+'" text-anchor="middle" transform="rotate(-90 '+(L-34)+' '+(T2+ph/2)+')">'+ylab+'</text>';
    svg.innerHTML=g;
  }

  ["dur-c","dur-T","dur-y"].forEach(function(id){ var e=document.getElementById(id); if(e) e.addEventListener("input", draw); });
  document.querySelectorAll("[data-set-lang]").forEach(function(b){ b.addEventListener("click", function(){ setTimeout(draw,10); }); });
  document.addEventListener("DOMContentLoaded", draw);
  draw();
})();
